import json, pathlib, re
base=pathlib.Path(r'C:\Users\豪\Downloads\upgrade_work')
data=json.loads((base/'data/songs.json').read_text())
# embed only initial catalog; actual user data will be persisted in IndexedDB
js=json.dumps(data, ensure_ascii=False, separators=(',',':'))
html=r'''<!doctype html>
<html lang="zh-CN">
<head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover,user-scalable=no">
<meta name="theme-color" content="#f7f4ee"><link rel="manifest" href="manifest.json"><title>诗经集</title>
<style>
:root{--bg:#f7f4ee;--card:#fffdf9;--ink:#292721;--muted:#8b877f;--line:#e9e3d9;--accent:#b87b45;--soft:#ead8c2;--danger:#b74c42;--shadow:0 8px 28px rgba(54,45,34,.06)}
*{box-sizing:border-box}html{background:var(--bg)}body{margin:0;background:var(--bg);color:var(--ink);font-family:-apple-system,BlinkMacSystemFont,"SF Pro Display","PingFang SC","Helvetica Neue",sans-serif;-webkit-font-smoothing:antialiased}button,input,textarea,select{font:inherit}button{cursor:pointer;color:inherit}
#app{max-width:560px;margin:auto;min-height:100vh}.page{display:none;padding:20px 18px calc(108px + env(safe-area-inset-bottom))}.page.active{display:block}.top{display:flex;justify-content:space-between;align-items:center;margin:8px 0 20px}.eyebrow{font-size:11px;color:var(--muted);letter-spacing:.04em}.brand{font-size:28px;font-weight:800;margin-top:3px}.btn{border:1px solid var(--line);background:var(--card);border-radius:14px;padding:10px 13px;box-shadow:0 2px 10px rgba(0,0,0,.02)}.circle{width:42px;height:42px;padding:0;display:grid;place-items:center;font-size:21px}.hero{background:linear-gradient(135deg,var(--soft),#f9eee1);border-radius:26px;padding:25px;box-shadow:var(--shadow)}.hero h1{font-size:27px;line-height:1.28;margin:8px 0}.hero p{color:#6f665c;line-height:1.75;margin:0}.darkbtn,.primary{background:var(--ink);color:#fff;border:0;border-radius:14px;padding:13px 16px}.darkbtn{margin-top:18px}.section{margin-top:27px}.sectionhead{display:flex;justify-content:space-between;align-items:center;margin-bottom:12px}.sectionhead h2{font-size:18px;margin:0}.search{display:flex;gap:9px;align-items:center;background:var(--card);border:1px solid var(--line);border-radius:16px;padding:12px 14px;margin-bottom:12px}.search input{border:0;outline:0;background:transparent;width:100%;min-width:0}.chips{display:flex;gap:8px;overflow:auto;padding-bottom:2px;scrollbar-width:none}.chips::-webkit-scrollbar{display:none}.chip{white-space:nowrap;border:1px solid var(--line);background:var(--card);padding:8px 13px;border-radius:999px;color:#716b64}.chip.active{background:var(--ink);color:#fff;border-color:var(--ink)}.song{background:var(--card);border:1px solid rgba(0,0,0,.035);border-radius:19px;padding:13px;display:flex;align-items:center;gap:11px;margin:9px 0;box-shadow:0 3px 16px rgba(54,45,34,.025)}.num{width:44px;height:44px;border-radius:14px;background:#f0e4d7;color:var(--accent);display:grid;place-items:center;font-size:12px;font-weight:750;flex:none}.info{flex:1;min-width:0}.info b{display:block;font-size:15px;margin-bottom:5px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.info small{color:var(--muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;display:block}.heart{border:0;background:transparent;font-size:21px;padding:7px;color:#aaa}.heart.on{color:var(--accent)}.badge{display:inline-block;font-size:10px;padding:4px 7px;border-radius:999px;background:#f0ebe3;color:#756d64;margin-left:5px}.empty{text-align:center;color:var(--muted);padding:42px 20px;line-height:1.8}.stats{display:grid;grid-template-columns:repeat(3,1fr);gap:9px}.stat{background:var(--card);border:1px solid var(--line);border-radius:18px;padding:15px}.stat b{display:block;font-size:22px;margin-top:4px}.row{display:flex;justify-content:space-between;align-items:center;padding:15px 0;border-bottom:1px solid var(--line)}.row:last-child{border-bottom:0}.listbox{background:var(--card);border-radius:20px;padding:5px 18px;box-shadow:var(--shadow)}.row.action{cursor:pointer}.row .chev{color:var(--muted)}
.nav{position:fixed;bottom:0;left:50%;transform:translateX(-50%);width:min(560px,100%);height:82px;padding-bottom:env(safe-area-inset-bottom);background:rgba(255,253,249,.94);backdrop-filter:blur(18px);border-top:1px solid var(--line);display:flex;align-items:center;justify-content:space-around;z-index:20}.tab{border:0;background:transparent;color:#999;text-align:center;font-size:11px;min-width:58px}.tab i{display:block;font-style:normal;font-size:21px;margin-bottom:3px}.tab.active{color:var(--ink)}.add{width:54px;height:54px;border-radius:19px;border:0;background:var(--ink);color:#fff;font-size:27px;box-shadow:0 7px 18px rgba(41,39,33,.22)}
.reader{display:none;min-height:100vh;padding:20px 20px calc(40px + env(safe-area-inset-bottom));background:linear-gradient(#faf7f1,#f5f0e8)}.reader.show{display:block}.readerbar{display:flex;justify-content:space-between}.readerbody{padding:62px 8px 20px;text-align:center}.readerbody h1{font-size:31px;line-height:1.25;margin:10px 0}.rnum{color:var(--accent);letter-spacing:2px}.meta{color:var(--muted);font-size:13px}.lyrics{text-align:left;white-space:pre-wrap;font-size:19px;line-height:2.15;margin:44px auto 0;max-width:510px}.placeholder{text-align:center;color:var(--muted);padding:25px 12px;border:1px dashed #d9d0c5;border-radius:18px;line-height:1.8}.actions{display:flex;justify-content:center;gap:12px;margin-top:40px}.round{width:48px;height:48px;border:1px solid var(--line);border-radius:50%;background:var(--card)}.reader.bottom-controls{padding-bottom:70px}
.form label{display:block;color:var(--muted);font-size:13px;margin:17px 0 7px}.field{width:100%;border:1px solid var(--line);background:var(--card);border-radius:14px;padding:13px;outline:none}.field:focus{border-color:var(--accent)}textarea.field{min-height:190px;resize:vertical}.primary{width:100%;margin-top:20px}.danger{background:#fff1ef;color:var(--danger);border:1px solid #f0d4d0;border-radius:14px;padding:12px 15px}.small{font-size:12px;color:var(--muted);line-height:1.7}.switch{display:flex;justify-content:space-between;align-items:center}.switch input{width:20px;height:20px}.range{width:100%}.toast{position:fixed;left:50%;bottom:100px;transform:translate(-50%,15px);background:#2b2925;color:#fff;padding:10px 15px;border-radius:12px;opacity:0;transition:.2s;z-index:40;font-size:13px;pointer-events:none}.toast.on{opacity:1;transform:translate(-50%,0)}.modal{position:fixed;inset:0;background:rgba(30,27,23,.38);display:none;align-items:flex-end;justify-content:center;z-index:50}.modal.show{display:flex}.sheet{width:min(560px,100%);background:var(--bg);border-radius:24px 24px 0 0;padding:18px 18px calc(20px + env(safe-area-inset-bottom));max-height:88vh;overflow:auto}.sheet h3{margin:4px 0 16px}.sheet .row{padding:13px 0}.sheet-actions{display:flex;gap:10px;margin-top:16px}.sheet-actions button{flex:1}.pillrow{display:flex;gap:8px;flex-wrap:wrap}.mini{padding:7px 10px;border:1px solid var(--line);background:var(--card);border-radius:999px;font-size:12px}.hidden{display:none!important}
</style></head><body>
<div id="app">
<section id="home" class="page active"></section><section id="library" class="page"></section><section id="fav" class="page"></section><section id="mine" class="page"></section><section id="addpage" class="page"></section><section id="reader" class="reader"></section>
<nav class="nav" id="nav"><button class="tab active" data-page="home"><i>⌂</i>首页</button><button class="tab" data-page="library"><i>☰</i>诗歌</button><button class="add" id="add">＋</button><button class="tab" data-page="fav"><i>♡</i>收藏</button><button class="tab" data-page="mine"><i>◉</i>我的</button></nav>
<div id="toast" class="toast"></div>
<div id="modal" class="modal"><div class="sheet" id="sheet"></div></div>
</div>
<script>
const SEED = __SEED__;
let songs=[],db=null,favs=new Set(),history=[],notes={},settings={fontSize:19,lineHeight:2.15,dark:false},playlists=[];
let filter='全部', query='', readerId=null;
const $=id=>document.getElementById(id);
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function toast(s){$('toast').textContent=s;$('toast').classList.add('on');clearTimeout(window.__toast);window.__toast=setTimeout(()=>$('toast').classList.remove('on'),1700)}
function openDB(){return new Promise((resolve,reject)=>{try{const r=indexedDB.open('shijing-local',2);r.onupgradeneeded=e=>{const d=e.target.result;if(!d.objectStoreNames.contains('state'))d.createObjectStore('state');if(!d.objectStoreNames.contains('songs'))d.createObjectStore('songs',{keyPath:'id'});};r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)}catch(e){reject(e)}})}
const tx=(store,mode='readonly')=>db.transaction(store,mode).objectStore(store);
function get(store,key){return new Promise((res,rej)=>{const r=tx(store).get(key);r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)})}
function getAll(store){return new Promise((res,rej)=>{const r=tx(store).getAll();r.onsuccess=()=>res(r.result||[]);r.onerror=()=>rej(r.error)})}
function put(store,v,key){return new Promise((res,rej)=>{const r=tx(store,'readwrite').put(v,key);r.onsuccess=()=>res();r.onerror=()=>rej(r.error)})}
function del(store,key){return new Promise((res,rej)=>{const r=tx(store,'readwrite').delete(key);r.onsuccess=()=>res();r.onerror=()=>rej(r.error)})}
async function init(){
 try{db=await openDB();const stored=await getAll('songs');if(!stored.length){for(const s of SEED) await put('songs',s)}songs=await getAll('songs');const state=await get('state','main')||{};favs=new Set(state.favs||[]);history=state.history||[];notes=state.notes||{};settings={...settings,...(state.settings||{})};playlists=state.playlists||[];applyTheme();renderHome();}
 catch(e){songs=SEED;renderHome();toast('本地存储不可用，当前以只读模式运行')}
}
async function saveState(){if(!db)return;await put('state',{favs:[...favs],history,notes,settings,playlists},'main')}
async function saveSong(s){songs=songs.filter(x=>x.id!==s.id);songs.push(s);songs.sort((a,b)=>(a.number||0)-(b.number||0)||String(a.id).localeCompare(String(b.id)));if(db)await put('songs',s)}
function card(s){const user=s.source==='user';return `<div class="song" onclick="openSong('${esc(s.id)}')"><div class="num">${esc(s.id)}</div><div class="info"><b>${esc(s.title)}${user?'<span class="badge">我的</span>':''}</b><small>${esc((s.tags||[]).join(' · '))}${s.author?' · '+esc(s.author):''}${s.lyrics?' · 有歌词':''}</small></div><button class="heart ${favs.has(s.id)?'on':''}" onclick="event.stopPropagation();fav('${esc(s.id)}')">${favs.has(s.id)?'♥':'♡'}</button></div>`}
function renderHome(){const recent=history.map(id=>songs.find(s=>s.id===id)).filter(Boolean).slice(0,3);$('home').innerHTML=`<div class="top"><div><div class="eyebrow">本地优先 · 离线可读</div><div class="brand">诗经集</div></div><button class="btn circle" onclick="show('library')">⌕</button></div><div class="hero"><div class="eyebrow">随身的诗歌库</div><h1>愿这首诗歌，陪你安静一会儿。</h1><p>目录、收藏、历史、笔记和你添加的诗歌都保存在设备本地。没有网络也可以阅读。</p><button class="darkbtn" onclick="openSong('${esc((recent[0]||songs[0]||{}).id||'001')}')">开始阅读 →</button></div><div class="section"><div class="sectionhead"><h2>最近阅读</h2><button class="btn" onclick="show('library')">全部</button></div>${recent.length?recent.map(card).join(''):'<div class="empty">还没有阅读记录<br>去诗歌库看看吧。</div>'}</div><div class="section"><div class="sectionhead"><h2>本地统计</h2></div><div class="stats"><div class="stat"><span class="eyebrow">诗歌</span><b>${songs.length}</b></div><div class="stat"><span class="eyebrow">收藏</span><b>${favs.size}</b></div><div class="stat"><span class="eyebrow">有歌词</span><b>${songs.filter(s=>s.lyrics).length}</b></div></div></div>`}
function renderLibrary(){ $('library').innerHTML=`<div class="top"><div><div class="eyebrow">本地数据库</div><div class="brand">诗歌库</div></div><button class="btn circle" onclick="show('addpage')">＋</button></div><div class="search"><span>⌕</span><input id="q" value="${esc(query)}" placeholder="搜索编号、标题、歌词、主题" oninput="query=this.value;results()"><button class="btn" style="padding:6px 9px" onclick="query='';renderLibrary()">清除</button></div><div class="chips">${['全部','诗经','唐诗','宋词','宋诗','乐府','汉魏','元曲','明清'].map(t=>`<button class="chip ${filter===t?'active':''}" onclick="filter='${t}';renderLibrary()">${t}</button>`).join('')}</div><div id="results"></div>`;results()}
function results(){const q=(query||'').trim().toLowerCase();const arr=songs.filter(s=>(filter==='全部'||(s.tags||[]).includes(filter))&&(!q||[s.id,s.number,s.title,s.author,s.lyrics,(s.tags||[]).join(' ')].join(' ').toLowerCase().includes(q)));const box=$('results');if(!box)return;box.innerHTML=`<div class="sectionhead" style="margin-top:22px"><h2>${arr.length} 首</h2><span style="color:var(--muted)">${filter}</span></div>${arr.slice(0,200).map(card).join('')||'<div class="empty">没有找到诗歌。</div>'}${arr.length>200?'<div class="empty">结果较多，仅显示前 200 首，请继续缩小搜索范围。</div>':''}`}
function renderFav(){const arr=songs.filter(s=>favs.has(s.id));$('fav').innerHTML=`<div class="top"><div><div class="eyebrow">我的收藏</div><div class="brand">收藏</div></div></div>${arr.map(card).join('')||'<div class="empty">还没有收藏。<br>在诗歌列表中点 ♡。</div>'}`}
function renderMine(){$('mine').innerHTML=`<div class="top"><div><div class="eyebrow">数据完全保存在本机</div><div class="brand">我的</div></div></div><div class="listbox"><div class="row"><span>诗歌总数</span><b>${songs.length}</b></div><div class="row"><span>收藏</span><b>${favs.size}</b></div><div class="row"><span>最近阅读</span><b>${history.length}</b></div><div class="row"><span>我的诗歌</span><b>${songs.filter(s=>s.source==='user').length}</b></div></div><div class="section"><div class="sectionhead"><h2>内容管理</h2></div><div class="listbox"><div class="row action" onclick="show('addpage')"><span>＋ 添加 / 编辑诗歌</span><span class="chev">›</span></div><div class="row action" onclick="importFile()"><span>📥 批量导入 JSON / TXT</span><span class="chev">›</span></div><div class="row action" onclick="exportAll()"><span>📤 备份全部本地数据</span><span class="chev">›</span></div><div class="row action" onclick="importBackup()"><span>♻️ 恢复备份</span><span class="chev">›</span></div><div class="row action" onclick="openSettings()"><span>⚙️ 阅读设置</span><span class="chev">›</span></div></div></div><div class="section"><div class="sectionhead"><h2>数据说明</h2></div><p class="small">已内置 1000 首经典诗词：诗经、唐诗三百首、宋词三百首及历代名篇，均为公有领域古籍原文，可离线阅读。你自己的诗歌会永久保存到 IndexedDB。</p></div>`}
function renderAdd(editId=''){const s=editId?songs.find(x=>x.id===editId):null;$('addpage').innerHTML=`<div class="top"><button class="btn circle" onclick="show('${s?'library':'library'}')">‹</button><div class="brand" style="font-size:20px">${s?'编辑诗歌':'添加诗歌'}</div><div style="width:42px"></div></div><div class="form"><label>编号</label><input id="sid" class="field" value="${esc(s?.id||'')}" placeholder="例如 1001" ${s?'readonly':''}><label>标题</label><input id="stitle" class="field" value="${esc(s?.title||'')}" placeholder="诗歌标题"><label>作者 / 译者</label><input id="sauthor" class="field" value="${esc(s?.author||'')}"><label>主题</label><input id="stags" class="field" value="${esc((s?.tags||[]).join(', '))}" placeholder="恩典, 安慰, 盼望"><label>歌词</label><textarea id="lyrics" class="field" placeholder="粘贴你有权使用的诗歌文本">${esc(s?.lyrics||'')}</textarea><label>备注</label><textarea id="snote" class="field" style="min-height:100px" placeholder="来源、版权状态、个人备注">${esc(s?.note||'')}</textarea><button class="primary" onclick="saveForm('${esc(editId)}')">保存到本地诗歌库</button>${s?`<button class="danger" style="width:100%;margin-top:10px" onclick="deleteSong('${esc(s.id)}')">删除这首诗歌</button>`:''}<p class="small">保存后即写入本机 IndexedDB，刷新页面不会丢失。</p></div>`}
async function saveForm(editId){let id=$('sid').value.trim(),title=$('stitle').value.trim();if(!id||!title){toast('请填写编号和标题');return}if(!editId&&songs.some(s=>s.id===id)){toast('编号已存在');return}const old=editId?songs.find(s=>s.id===editId):null;const s={id,number:Number(id)||0,title,author:$('sauthor').value.trim(),tags:$('stags').value.split(/[,，]/).map(x=>x.trim()).filter(Boolean),lyrics:$('lyrics').value,note:$('snote').value,source:'user',copyrightStatus:old?.copyrightStatus||'用户自行确认'};await saveSong(s);toast('已保存');show('library')}
async function deleteSong(id){if(!confirm('确定删除这首用户诗歌？'))return;await del('songs',id);songs=songs.filter(s=>s.id!==id);favs.delete(id);history=history.filter(x=>x!==id);delete notes[id];await saveState();toast('已删除');show('library')}
async function fav(id){favs.has(id)?favs.delete(id):favs.add(id);await saveState();renderHome();renderLibrary();renderFav();renderMine();if(readerId===id)renderReader();toast(favs.has(id)?'已收藏':'已取消收藏')}
function openSong(id){const s=songs.find(x=>x.id===id);if(!s)return;readerId=id;history=[id,...history.filter(x=>x!==id)].slice(0,30);saveState();renderReader();$('nav').style.display='none';document.querySelectorAll('.page').forEach(x=>x.classList.remove('active'));$('reader').classList.add('show')}
function renderReader(){const s=songs.find(x=>x.id===readerId);if(!s)return;const lyric=s.lyrics?`<div class="lyrics">${esc(s.lyrics)}</div>`:`<div class="placeholder">这首诗歌暂缺正文。<br>你可以在「我的 → 添加 / 编辑诗歌」中补充你有权使用的文本。</div>`;$('reader').innerHTML=`<div class="readerbar"><button class="btn circle" onclick="closeReader()">‹</button><button class="btn circle" onclick="fav('${esc(s.id)}')">${favs.has(s.id)?'♥':'♡'}</button></div><div class="readerbody"><div class="rnum">${esc(s.id)}</div><h1>${esc(s.title)}</h1><div class="meta">${esc(s.author||'')}${s.tags?.length?' · '+esc(s.tags.join(' · ')):''}</div>${lyric}<div class="actions"><button class="round" onclick="speakCurrent()">🔊</button><button class="round" onclick="shareCurrent()">↗</button><button class="round" onclick="editSong('${esc(s.id)}')">✎</button><button class="round" onclick="openNote('${esc(s.id)}')">📝</button></div>${notes[s.id]?`<div class="section" style="text-align:left"><div class="sectionhead"><h2>我的笔记</h2><button class="btn" onclick="openNote('${esc(s.id)}')">编辑</button></div><div class="listbox" style="padding:15px;line-height:1.8;white-space:pre-wrap">${esc(notes[s.id])}</div></div>`:''}</div>`}
function closeReader(){$('reader').classList.remove('show');$('nav').style.display='flex';show('library')}
function editSong(id){renderAdd(id);show('addpage')}
function shareCurrent(){const s=songs.find(x=>x.id===readerId);if(!s)return;const text=`《${s.title}》\n${s.lyrics||''}`;if(navigator.share)navigator.share({title:s.title,text}).catch(()=>{});else navigator.clipboard?.writeText(text).then(()=>toast('已复制'))}
function speakCurrent(){const s=songs.find(x=>x.id===readerId);if(!s?.lyrics){toast('这首诗歌暂无歌词');return}if(!('speechSynthesis'in window)){toast('当前浏览器不支持朗读');return}speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(s.lyrics);u.lang='zh-CN';u.rate=.85;speechSynthesis.speak(u)}
function openNote(id){$('sheet').innerHTML=`<h3>我的笔记</h3><textarea id="noteText" class="field" placeholder="写下这首诗歌带给你的感受、祷告或重点">${esc(notes[id]||'')}</textarea><div class="sheet-actions"><button class="btn" onclick="closeModal()">取消</button><button class="primary" onclick="saveNote('${esc(id)}')">保存</button></div>`;$('modal').classList.add('show')}
async function saveNote(id){notes[id]=$('noteText').value.trim();if(!notes[id])delete notes[id];await saveState();closeModal();renderReader();toast('笔记已保存')}
function openSettings(){$('sheet').innerHTML=`<h3>阅读设置</h3><div class="row"><span>字体大小</span><span><input id="fontSize" class="range" type="range" min="15" max="28" value="${settings.fontSize}"></span></div><div class="row"><span>行距</span><span><input id="lineHeight" class="range" type="range" min="1.5" max="2.8" step=".05" value="${settings.lineHeight}"></span></div><div class="row switch"><span>深色阅读</span><input id="dark" type="checkbox" ${settings.dark?'checked':''}></div><div class="sheet-actions"><button class="btn" onclick="closeModal()">取消</button><button class="primary" onclick="saveSettings()">保存</button></div>`;$('modal').classList.add('show')}
async function saveSettings(){settings.fontSize=Number($('fontSize').value);settings.lineHeight=Number($('lineHeight').value);settings.dark=$('dark').checked;applyTheme();await saveState();closeModal();if(readerId)renderReader();toast('设置已保存')}
function applyTheme(){document.documentElement.style.setProperty('--bg',settings.dark?'#171614':'#f7f4ee');document.documentElement.style.setProperty('--card',settings.dark?'#23211e':'#fffdf9');document.documentElement.style.setProperty('--ink',settings.dark?'#f4f0e8':'#292721');document.documentElement.style.setProperty('--muted',settings.dark?'#aaa39a':'#8b877f');document.documentElement.style.setProperty('--line',settings.dark?'#3a3732':'#e9e3d9');document.documentElement.style.setProperty('--soft',settings.dark?'#3a3026':'#ead8c2')}
function closeModal(){$('modal').classList.remove('show')}
$('modal').onclick=e=>{if(e.target===$('modal'))closeModal()}
function exportAll(){const payload={version:2,exportedAt:new Date().toISOString(),songs,favs:[...favs],history,notes,settings,playlists};download('诗经集-完整备份.json',JSON.stringify(payload,null,2),'application/json');toast('备份已导出')}
function importFile(){const i=document.createElement('input');i.type='file';i.accept='.json,.txt,.csv';i.onchange=()=>{const f=i.files[0];if(!f)return;const r=new FileReader();r.onload=()=>handleImport(String(r.result),f.name);r.readAsText(f)};i.click()}
async function handleImport(text,name){try{let arr=[];if(name.toLowerCase().endsWith('.json')){const d=JSON.parse(text);arr=Array.isArray(d)?d:(d.songs||[]);if(d.favs){favs=new Set(d.favs)}if(d.history)history=d.history;if(d.notes)notes=d.notes;if(d.settings)settings={...settings,...d.settings};if(d.playlists)playlists=d.playlists}else{const blocks=text.split(/\n\s*\n/).map(x=>x.trim()).filter(Boolean);arr=blocks.map((b,i)=>{const lines=b.split(/\r?\n/);return{id:String(lines[0]?.match(/\d+/)?.[0]||Date.now()+i),number:Number(lines[0]?.match(/\d+/)?.[0]||0),title:lines[0].replace(/^\s*\d+[.、\s-]*/,'').trim()||`导入诗歌 ${i+1}`,author:'',tags:['未分类'],lyrics:lines.slice(1).join('\n'),source:'user',copyrightStatus:'用户自行确认'}})}let n=0;for(const raw of arr){if(!raw?.id||!raw?.title)continue;const s={id:String(raw.id),number:Number(raw.number)||Number(String(raw.id).replace(/\D/g,''))||0,title:String(raw.title),author:String(raw.author||''),tags:Array.isArray(raw.tags)?raw.tags:String(raw.tags||'').split(/[,，]/).map(x=>x.trim()).filter(Boolean),lyrics:String(raw.lyrics||''),note:String(raw.note||''),source:'user',copyrightStatus:String(raw.copyrightStatus||'用户自行确认')};if(songs.some(x=>x.id===s.id)){const old=songs.find(x=>x.id===s.id);if(old.source!=='user'&&s.source==='user'){} else if(old.source==='user'){} else {continue}}await saveSong(s);n++}await saveState();applyTheme();toast(`已导入 ${n} 首`);renderMine();renderLibrary()}catch(e){console.error(e);toast('导入失败，请检查文件格式')}}
function importBackup(){importFile()}
function download(name,data,type){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([data],{type}));a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function show(id){document.querySelectorAll('.page').forEach(x=>x.classList.remove('active'));$('reader').classList.remove('show');$(id).classList.add('active');document.querySelectorAll('.tab').forEach(x=>x.classList.toggle('active',x.dataset.page===id));const fn={home:renderHome,library:renderLibrary,fav:renderFav,mine:renderMine,addpage:()=>renderAdd()}[id];if(fn)fn()}
document.querySelectorAll('.tab').forEach(b=>b.onclick=()=>show(b.dataset.page));$('add').onclick=()=>show('addpage');init();
if('serviceWorker'in navigator){navigator.serviceWorker.register('sw.js').catch(()=>{})}
</script></body></html>'''
html=html.replace('__SEED__',js)
(base/'index.html').write_text(html,encoding='utf-8')
